  if (/(^|[\/\-])(20)?(\d{2})[\-\/](20)?(\d{2})([\/\-]|$)/.test(tok)){
    const m = tok.match(/(?:20)?(\d{2})[\-\/](?:20)?(\d{2})/);
    if (m && (+m[1] + 1) % 100 === +m[2] % 100) s += 6;       // financial year inside: 2026-27
  }
