  if (tok.length >= 5) s += 1;
  if (/^(b|t|a|c|d|e|f|g|h|plot|sector|block|flat|shop|unit|floor|gali|wz|rz)[\-\/]?\d{1,3}$/i.test(tok)) s -= 4;   // address bits: B-17, T-01, Sector-3
