  const head = n ? "Posting to " + tname + ": " + d + " of " + n + " done" : "Posting to " + tname;
  return head + (pj.message && !/^(Posting|Starting|Resuming|Finding)/.test(pj.message) ? " \u2014 " + pj.message : "\u2026");
