    const qn = GSTR.nextYm(GSTSet.qEnd(ym));
    if (t === "comp") return which === "cmp08" ? d(qn, "18") : "";
    if (!GSTSet.isQEnd(ym)) return which === "iff" ? d(GSTR.nextYm(ym), "13") : which === "pmt06" ? d(GSTR.nextYm(ym), "25") : "";
