      const by = {};
      (b.vouchers || []).filter(v => !v.opt && !v.cancel).forEach(v => v.ent.forEach(e => { (by[e.l] = by[e.l] || []).push([String(v.date).slice(0, 6), e.a]); }));
      Object.values(by).forEach(l => l.sort((a, c) => a[0].localeCompare(c[0])));
