function viewHelp(){ return '<div data-react="Help"></div>'; }
// typed or chosen: the guide's search (the best article opens), the ticket searches, the reply, the desk's filters
function supType(k, v, now){
  const s = SUP.st(); s[k] = v;
  if (k === "gq"){ const r = GUIDE.search(v); if (r[0]) s.art = r[0].k; }
  if (k === "rtext" && !now){ FinComReact.redraw(); return; }
  render();
}
function supDraft(k, v, now){ const s = SUP.st(); (s.draft = s.draft || {})[k] = v; if (now) render(); else FinComReact.redraw(); }
function supTab(id){ const s = SUP.st(); s.tab = id; s.open = null; s.newOpen = false; render(); if (id !== "guide" && SUP.on()) SUP.load(true); }
function supArt(k, go){ const s = SUP.st(); s.art = k; if (go){ s.newOpen = false; s.tab = "guide"; } render(); }
function supFilter(f){ SUP.st().filter = f; render(); }
function supDstat(k){ SUP.st().dstat = k; render(); }
function supFiles(which, files){ const s = SUP.st(); s[which] = (s[which] || []).concat(files).slice(0, 8); render(); }
function supFdel(which, i){ SUP.st()[which].splice(i, 1); render(); }
function supDl(path, name){ SUP.download(path, name).catch(err => toast(err.message)); }
async function supSet(k, v){ const s = SUP.st(); try { await SUP.set({[k]: v}); await SUP.open(s.open); SUP.load(true); toast("Saved."); } catch (err){ toast(err.message); render(); } }
async function supAct(a){
  const s = SUP.st();
  if (a === "new"){ s.newOpen = true; s.open = null; s.draft = null; s.files = []; if (!S.helpCtx) S.helpCtx = SUP.context(); render(); return; }
  if (a === "cancel"){ s.newOpen = false; s.draft = null; s.files = []; render(); return; }
  if (a === "back"){ s.open = null; s.detail = null; render(); return; }
  if (a === "reload"){ SUP.load(false); return; }
  if (a === "submit"){
    const dr = s.draft || {};
    if (String(dr.subject || "").trim().length < 3){ toast("Give the ticket a subject."); return; }
    if (String(dr.body || "").trim().length < 5){ toast("Describe what happened."); return; }
    s.busy = true; render();
    try { const tk = await SUP.create(dr); s.newOpen = false; s.draft = null; s.files = []; s.tab = "tickets"; s.busy = false; S.helpCtx = null; toast("Ticket " + SUP.code(tk) + " raised. FinCom support will answer here."); await SUP.load(true); SUP.open(tk.id); }
    catch (err){ s.busy = false; toast("Not raised: " + err.message); render(); }
    return;
  }
  if (a === "send"){
    const body = String(s.rtext || "").trim(), internal = !!s.rint;
    if (!body && !(s.rfiles || []).length){ toast("Write a reply or attach a file."); return; }
    s.busy = true; render();
    try { await SUP.reply(body, internal); s.rfiles = []; s.rtext = ""; s.rint = false; s.busy = false; await SUP.open(s.open); SUP.load(true); toast(internal ? "Note added." : "Sent."); }
    catch (err){ s.busy = false; toast("Not sent: " + err.message); render(); }
    return;
  }
  if (a === "resolve" || a === "reopen"){ try { await SUP.set({p_status: a === "resolve" ? "resolved" : "open"}); await SUP.open(s.open); SUP.load(true); } catch (err){ toast(err.message); } }
}

if (typeof document !== "undefined"){
  // what went wrong lately goes with a ticket: errors, and the messages shown at the foot of the screen
  if (typeof toast === "function"){ const shown = toast; toast = function(m){ try { SUP.note("msg", m); } catch (e){} return shown.apply(this, arguments); }; }
  window.addEventListener("error", e => SUP.note("error", (e && e.message) || "error"));
  window.addEventListener("unhandledrejection", e => SUP.note("error", (e && e.reason && (e.reason.message || e.reason)) || "rejected"));
}
/* ================================================================== */
/* Books sync: each client's TDS and GST work in the firm's database  */
/* ================================================================== */
// Before this, challans, allocations, certificates, 2B, returns filed and every other piece of TDS and GST work lived
// only in the browser that did it. Now that work (the "work" part of the books) is kept in Supabase, in the table
// client_books, one row per client, with a revision number:
//   - every save says which revision it was built on; the database refuses a save built on an old one;
//   - a refused save is merged, three ways, against what the other person saved: changes to different things are both
//     kept; where both changed the same thing, the database's copy stays and this browser's copy is kept in
//     client_books_history (note "conflict"), so nothing is lost;
//   - every earlier revision is kept in client_books_history.
// The day book and the balances read from Tally are shared through FinCom's cloud copy of the books (49-tally-cloud.js);
// the ledger masters are shared here with the work.
// If the database does not have client_books yet (migration not applied), the books work as before, in this browser.
const BookSync = {
  PART: "work",
  // read from Tally and worked out from it again at any time: not sent
  // (the ledger masters are shared: a colleague sees the same groups, PANs and ledger details; the day book and the
  // balances are shared through the cloud copy of the books)
  FROM_TALLY: ["vouchers", "meta", "tb", "mis"],
  st: {},            // cid -> {rev, base, timer, busy, again, error, at, by, readonly}
  off: false,        // the database has no client_books: work only in this browser
  wait: 1500,
  keys(){ return BOOKS_KEYS.filter(k => this.FROM_TALLY.indexOf(k) < 0); },
  of(cid){ return this.st[cid] || (this.st[cid] = {rev: null, base: null}); },
  on(){ return !this.off && typeof Cloud === "object" && Cloud.on() && !!Cloud.st.firm; },
  // the work part of a client's books, as plain data (no undefined, so it compares the same after a round trip)
  work(b){ const w = {}; this.keys().forEach(k => { if (b && b[k] !== undefined) w[k] = b[k]; }); return JSON.parse(JSON.stringify(w)); },
  same(a, b){ return stableStr(a === undefined ? null : a) === stableStr(b === undefined ? null : b); },
  /* ---------- what this browser last agreed with the database ---------- */
  async loadBase(cid){
    const s = this.of(cid);
    if (s.rev !== null) return s;
    try { const m = await IDBStore.get("booksync:" + cid); if (m){ s.rev = m.rev; s.base = m.base; } } catch (e){}
    if (s.rev === null){ s.rev = 0; s.base = {}; }
    return s;
  },
  async keepBase(cid, rev, base){
    const s = this.of(cid); s.rev = rev; s.base = base;
    try { await IDBStore.write([["booksync:" + cid, {rev, base, at: new Date().toISOString()}]]); } catch (e){}
  },
  /* ---------- three-way merge ---------- */
  // base: what both started from; mine: this browser; theirs: the database. Returns the merged value;
  // every place both changed differently is added to `clash` (the database's value is kept there).
  merge(base, mine, theirs, path, clash){
    if (this.same(mine, theirs)) return mine;
    if (this.same(base, mine)) return theirs;
    if (this.same(base, theirs)) return mine;
    const obj = v => v && typeof v === "object" && !Array.isArray(v);
    const byId = v => Array.isArray(v) && v.every(x => x && typeof x === "object" && typeof x.id === "string" && x.id);
    if (obj(mine) && obj(theirs)){
      const b = obj(base) ? base : {}, out = {};
      new Set(Object.keys(theirs).concat(Object.keys(mine))).forEach(k => {
        const v = this.merge(b[k], mine[k], theirs[k], path.concat(k), clash);
        if (v !== undefined) out[k] = v;
      });
      return out;
    }
    if (byId(mine) && byId(theirs) && (base === undefined || byId(base))){
      const map = a => { const m = {}; (a || []).forEach(x => { m[x.id] = x; }); return m; };
      const B = map(base), M = map(mine), T = map(theirs), out = [];
      const ids = theirs.map(x => x.id).concat(mine.map(x => x.id).filter(id => !(id in T)));
      ids.forEach(id => { const v = this.merge(B[id], M[id], T[id], path.concat(id), clash); if (v !== undefined) out.push(v); });
      return out;
    }
    clash.push(path.join(" › ") || "(all)");
    return theirs;
  },
  /* ---------- the database ---------- */
  async rpc(fn, args){ return Cloud.api("rpc/" + fn, {method: "POST", body: args}); },
  missing(e){ return /save_client_books|client_books|keep_books_conflict|PGRST202|PGRST205|schema cache|does not exist|404/i.test(String(e && e.message || e)); },
  async fetch(cid){
    const rows = await Cloud.api("client_books?select=rev,data,updated_at,updated_by&client_id=eq." + encodeURIComponent(cid) + "&part=eq." + this.PART);
    return rows && rows[0] ? rows[0] : null;
  },
  // put what came back into the open books (and this browser's copy)
  // server-books: what Tally's masters give (the ledgers' groups, GSTINs, states...) is filled by the cloud copy too; a work
  // part without them must not wipe what the cloud copy just brought in (another computer then showed MIS with no groups)
  MASTERS: ["under", "groups", "gstins", "states", "groupInfo", "ledInfo", "ledInfoAt", "tallyCo"],
  async apply(cid, data){
    const keys = this.keys(), drop = k => data[k] === undefined && this.MASTERS.indexOf(k) < 0;
    if (S.books && S.books.cid === cid){
      keys.forEach(k => { if (drop(k)) delete S.books[k]; else if (data[k] !== undefined) S.books[k] = clone(data[k]); });
      if (S.books.vouchers && S.books.vouchers.length) try { LedMaster.refresh(S.books); } catch (e){}
      await saveBooks({fromCloud: true});
      render();
    } else {
      const saved = (await Books.load(cid)) || {cid};
      keys.forEach(k => { if (drop(k)) delete saved[k]; else if (data[k] !== undefined) saved[k] = data[k]; });
      await Books.save(cid, saved);
    }
  },
  async localWork(cid){
    if (S.books && S.books.cid === cid && !S.books.loading) return this.work(S.books);
    const saved = await Books.load(cid);
    return saved ? this.work(saved) : null;
  },
  who(uid){ const m = ((Cloud.st && Cloud.st.members) || []).find(x => x.user_id === uid); return m ? (m.name || m.email) : "someone else"; },
  tell(cid, clash, by){
    if (!clash.length) return;
    const co = S.companies[cid], name = co ? co.name : cid;
    toast(name + ": " + this.who(by) + " changed the same TDS/GST items you did (" + clash.slice(0, 3).join("; ") + (clash.length > 3 ? " and " + (clash.length - 3) + " more" : "") +
      "). Their version is kept; yours is saved in the history.");
  },
  /* ---------- sending ---------- */
  schedule(cid){
    if (!this.on() || !cid) return;
    if (typeof BookItems === "object" && BookItems.on()){ BookItems.schedule(cid); return; }     // live sync: item by item, at once (54-live-sync.js)
    const s = this.of(cid);
    clearTimeout(s.timer);
    s.timer = setTimeout(() => this.push(cid), this.wait);
  },
  async push(cid){
    if (!this.on()) return;
    const s = this.of(cid);
    if (s.busy){ s.again = true; return; }
    if (s.readonly) return;
    s.busy = true; s.error = "";
    try {
      await this.loadBase(cid);
      for (let round = 0; round < 4; round++){
        const mine = await this.localWork(cid);
        if (!mine || (s.rev === 0 && !Object.keys(mine).length)) break;   // nothing to send yet
        if (s.rev > 0 && this.same(mine, s.base)) break;          // nothing new here
        const res = await this.rpc("save_client_books", {p_client: cid, p_part: this.PART, p_base: s.rev, p_data: mine});
        if (res && res.ok){ await this.keepBase(cid, res.rev, mine); s.at = Date.now(); break; }
        // someone saved first: merge with theirs and try again on top of their revision
        const theirs = (res && res.data) || {}, clash = [];
        const merged = this.merge(s.base || {}, mine, theirs, [], clash);
        if (clash.length){ try { await this.rpc("keep_books_conflict", {p_client: cid, p_part: this.PART, p_rev: res.rev, p_data: mine}); } catch (e){} }
        await this.keepBase(cid, res.rev, theirs);
        await this.apply(cid, merged);
        this.tell(cid, clash, res.updated_by);
      }
    } catch (e){
      if (this.missing(e)) this.off = true;
      else if (/not allowed|42501|permission/i.test(e.message)) s.readonly = true;
      else s.error = e.message;
    }
    s.busy = false;
    if (s.again){ s.again = false; this.schedule(cid); }
  },
  /* ---------- receiving ---------- */
  async pull(cid){
    if (!this.on() || !cid) return;
    if (typeof BookItems === "object" && BookItems.on()){ try { if (await BookItems.pull(cid) !== "off") return; } catch (e){ this.of(cid).error = e.message; return; } }
    const s = this.of(cid);
    if (s.busy) return;
    s.busy = true;
    let upload = false;
    try {
      await this.loadBase(cid);
      const row = await this.fetch(cid);
      if (!row){ upload = true; }                                    // first time: this browser's work goes up
      else if (row.rev !== s.rev){
        const mine = (await this.localWork(cid)) || {}, clash = [];
        const merged = s.rev === 0 && !Object.keys(s.base || {}).length && !Object.keys(mine).length ? row.data : this.merge(s.base || {}, mine, row.data || {}, [], clash);
        if (clash.length){ try { await this.rpc("keep_books_conflict", {p_client: cid, p_part: this.PART, p_rev: row.rev, p_data: mine}); } catch (e){} }
        await this.keepBase(cid, row.rev, row.data || {});
        await this.apply(cid, merged);
        this.tell(cid, clash, row.updated_by);
        upload = !this.same(merged, row.data || {});               // this browser had changes of its own
      } else {
        const mine = await this.localWork(cid);
        upload = !!mine && !this.same(mine, s.base);
      }
      s.by = row ? row.updated_by : null; s.at = Date.now(); s.error = "";
    } catch (e){
      if (this.missing(e)) this.off = true; else s.error = e.message;
    }
    s.busy = false;
    if (upload) await this.push(cid);
  },
  // called with every firm sync: send what is waiting, bring in what others saved for the client that is open
  async tick(){
    if (!this.on()) return;
    if (typeof BookItems === "object" && BookItems.on()){ await BookItems.flush(); const o = S.books && S.books.cid && !S.books.loading ? S.books.cid : null; if (o) await BookItems.pull(o).catch(() => {}); return; }
    const open = S.books && S.books.cid && !S.books.loading ? S.books.cid : null;
    for (const cid of Object.keys(this.st)){ if (cid !== open && this.st[cid].timer && !this.st[cid].busy) await this.push(cid); }
    if (open) await this.pull(open);
  },
  // one line under the books' tabs
  // information on the From Tally tab only; warnings (look-only, not saved) on every tab

};
if (typeof window === "object") window.addEventListener("beforeunload", () => { try { if (typeof BookItems === "object") Object.keys(BookItems.st).forEach(cid => { if (BookItems.st[cid].timer){ clearTimeout(BookItems.st[cid].timer); BookItems.push(cid); } }); } catch (e){} try { Object.keys(BookSync.st).forEach(cid => { if (BookSync.st[cid].timer){ clearTimeout(BookSync.st[cid].timer); BookSync.push(cid); } }); } catch (e){} });
/* ================================================================== */
/* Vendor ledger reconciliation: the vendor's ledger against the      */
/* party's ledger in Tally, for a period, with a downloadable report   */
/* ================================================================== */
// Everything is turned into one measure: the amount this client owes the vendor ("payable").
//   In Tally, a credit to the vendor's ledger (a bill) raises it; a debit (a payment, a debit note) lowers it.
//   In the vendor's own books it is the other way round: their debit (a bill to us) raises it.
// The vendor's file is read by the same reader as bank statements (Excel, CSV, PDF, scans), which gives each line
// a debit, a credit and a running balance; which side is which is found by matching amounts against Tally.
const VR = {
  def(){
    const co = CO(), today = new Date().toISOString().slice(0, 10);
    const y = +today.slice(0, 4), m = +today.slice(5, 7), fy = m >= 4 ? y : y - 1;
    return {open: true, cid: co.id, ledger: "", from: fy + "-04-01", to: today, file: null, fileName: "", res: null, busy: ""};
  },
  st(){ if (!S.vrec || S.vrec.cid !== S.coId) S.vrec = null; return S.vrec; },
  ledgers(){
    const list = typeof knownLedgers === "function" && B() ? Array.from(knownLedgers().values()) : [];
    const cred = l => /creditor|debtor|payable|supplier/i.test(l.group || "");
    return list.slice().sort((a, b) => (cred(b) - cred(a)) || a.name.localeCompare(b.name));
  },
  refs(s){
    // document numbers in a line: tokens with a digit, at least 3 long, without spaces or leading zeros
    return Array.from(new Set(String(s || "").toUpperCase().split(/[\s,;:()|]+/).map(t => t.replace(/[^A-Z0-9\/-]/g, "").replace(/^0+/, ""))
      .filter(t => t.length >= 3 && /\d/.test(t) && !/^\d{1,2}[\/-]\d{1,2}[\/-]\d{2,4}$/.test(t))));
  }
};

async function runVendorRecon(){
  const V0 = VR.st();
  if (!V0) return;
  const co = CO();
  const ledger = exactLedger(V0.ledger);
  if (!ledger){ toast("Choose the vendor's ledger as it is in Tally (start typing its name)."); return; }
  if (!V0.file){ toast("Choose the vendor's ledger file (Excel, CSV or PDF)."); return; }
  if (!V0.from || !V0.to || V0.from > V0.to){ toast("Choose the dates: from, and up to."); return; }
  const tname = await ensureTallyCompany(co);
  if (!tname) return;
  const setBusy = t => { V0.busy = t; render(); };
  try {
    setBusy("Reading the vendor's ledger…");
    const parsed = await readStatement(V0.file, p => setBusy("Reading the vendor's ledger… " + (p && p.page ? "page " + p.page + (p.pages ? " of " + p.pages : "") : "")));
    const vrows = [].concat(parsed.rows || []).filter(r => r.date && (num(r.debit) || num(r.credit)));
    if (!vrows.length) throw {message: "No entries could be read from " + V0.fileName + "."};
    setBusy("Reading " + ledger + " from Tally…");
    const tb = await tallyBankBalance(tname, ledger, V0.to);                 // -(Tally's figure): a credit balance comes out negative
    const jl = await Bridge.call(ledgerLinesUrl(tname, ledger, V0.from, V0.to), null, 600000);
    if (!Array.isArray(jl.vouchers)) throw {message: "Tally did not return the entries of " + ledger + "."};
    setBusy("Matching the entries…");
    const T = [];
    jl.vouchers.filter(v => !/^yes$/i.test(v.cancelled || "")).forEach(v => {
      const be = [].concat(v.entries || []).find(e => norm(e.ledger) === norm(ledger));
      if (!be) return;
      const date = tallyToIso(v.date);
      if (date < V0.from || date > V0.to) return;
      const other = [].concat(v.entries || []).find(e => norm(e.ledger) !== norm(ledger));
      const bills = [].concat(be.bills || []).map(x => typeof x === "string" ? x : (x && x.name) || "").filter(Boolean);
      T.push({i: T.length, date, type: v.type || "", number: v.number || "", ref: v.reference || "", bills, other: (other && other.ledger) || "",
        narr: String(v.narration || ""), eff: r2(parseFloat(String(be.amount).replace(/,/g, "")) || 0)});
    });
    T.forEach(t => { t.refs = VR.refs([t.ref, t.number, t.bills.join(" "), t.narr].join(" ")); });
    const tClose = r2(-tb.close), tOpen = r2(tClose - T.reduce((a, t) => a + t.eff, 0));
    // which side of the vendor's file is a bill to us: the reading that matches more of Tally's amounts
    const inPeriod = vrows.filter(r => r.date >= V0.from && r.date <= V0.to);
    const bag = new Map(); T.forEach(t => { const k = t.eff.toFixed(2); bag.set(k, (bag.get(k) || 0) + 1); });
    const score = s => { const b2 = new Map(bag); let n = 0; inPeriod.forEach(r => { const k = r2(s * (num(r.debit) - num(r.credit))).toFixed(2); if (b2.get(k)){ n++; b2.set(k, b2.get(k) - 1); } }); return n; };
    const sA = score(1), sB = score(-1), s = sB > sA ? -1 : 1;
    const V = inPeriod.map((r, i) => ({i, date: r.date, narr: String(r.narr || ""), eff: r2(s * (num(r.debit) - num(r.credit))), refs: VR.refs(r.narr), bal: r.balance == null ? null : r2(-s * num(r.balance))}));
    // the vendor's opening and closing, in the same measure
    const meta = parsed.meta || {};
    const firstIdx = vrows.findIndex(r => r.date >= V0.from);
    let vOpen = null;
    if (firstIdx > 0 && vrows[firstIdx - 1].balance != null) vOpen = r2(-s * num(vrows[firstIdx - 1].balance));
    else if (firstIdx === 0 && meta.opening !== undefined && meta.opening !== null && vrows[0].date >= V0.from) vOpen = r2(-s * num(meta.opening));
    else if (V.length && V[0].bal !== null) vOpen = r2(V[0].bal - V[0].eff);
    const lastIn = V.length ? V[V.length - 1] : null;
    let vClose = lastIn && lastIn.bal !== null ? lastIn.bal : null;
    if (vClose === null && vOpen !== null) vClose = r2(vOpen + V.reduce((a, x) => a + x.eff, 0));
    if (vOpen === null && vClose !== null) vOpen = r2(vClose - V.reduce((a, x) => a + x.eff, 0));
    // pair them: same amount with a shared document number; then same amount within a week; then within 60 days
    const pairs = [], usedT = new Set(), usedV = new Set();
    const days = (a1, b1) => Math.abs((new Date(a1) - new Date(b1)) / 864e5);
    const pass = test => V.forEach(v => {
      if (usedV.has(v.i)) return;
      let best = null;
      T.forEach(t => { if (usedT.has(t.i) || Math.abs(t.eff - v.eff) >= 0.01 || !test(v, t)) return; const d = days(v.date, t.date); if (!best || d < best.d) best = {t, d}; });
      if (best){ usedV.add(v.i); usedT.add(best.t.i); pairs.push({v: v.i, t: best.t.i}); }
    });
    const shared = (v, t) => v.refs.some(x => t.refs.includes(x));
    pass((v, t) => shared(v, t));
    pass((v, t) => days(v.date, t.date) <= 7);
    pass((v, t) => days(v.date, t.date) <= 60);
    // the same document on both sides with another amount
    const differ = [];
    V.forEach(v => { if (usedV.has(v.i) || !v.refs.length) return; const t = T.find(t2 => !usedT.has(t2.i) && Math.sign(t2.eff) === Math.sign(v.eff) && shared(v, t2)); if (t){ usedV.add(v.i); usedT.add(t.i); differ.push({v: v.i, t: t.i}); } });
    // no shared number: the same kind of entry within 3 days, with an amount within 10%, is taken as the same document
    V.forEach(v => { if (usedV.has(v.i)) return; const t = T.find(t2 => !usedT.has(t2.i) && Math.sign(t2.eff) === Math.sign(v.eff) && days(v.date, t2.date) <= 3 && Math.abs(t2.eff - v.eff) <= 0.1 * Math.abs(v.eff)); if (t){ usedV.add(v.i); usedT.add(t.i); differ.push({v: v.i, t: t.i}); } });
    const onlyV = V.filter(v => !usedV.has(v.i)), onlyT = T.filter(t => !usedT.has(t.i));
    const sum = (list, f) => r2(list.reduce((a, x) => a + f(x), 0));
    const openDiff = vOpen === null ? null : r2(vOpen - tOpen);
    const vEff = sum(onlyV, x => x.eff), tEff = sum(onlyT, x => x.eff), dEff = sum(differ, d => V[d.v].eff - T[d.t].eff);
    const unexplained = vClose === null ? null : r2(vClose - (tClose + (openDiff || 0) + vEff - tEff + dEff));
    // where the running balances move apart: every date on which the difference changes, and what caused it
    const timeline = [];
    if (vOpen !== null){
      const dates = Array.from(new Set(V.map(x => x.date).concat(T.map(x => x.date)))).sort();
      let tb2 = tOpen, vb = vOpen, prev = r2(vOpen - tOpen);
      if (Math.abs(prev) >= 0.01) timeline.push({date: V0.from, diff: prev, change: prev, why: ["opening balances differ"]});
      dates.forEach(d => {
        V.filter(x => x.date === d).forEach(x => { vb += x.eff; });
        T.filter(x => x.date === d).forEach(x => { tb2 += x.eff; });
        const diff = r2(vb - tb2);
        if (Math.abs(diff - prev) >= 0.01){
          const why = onlyV.filter(x => x.date === d).map(x => "vendor only: " + INR.format(x.eff) + " " + x.narr.slice(0, 40))
            .concat(onlyT.filter(x => x.date === d).map(x => "Tally only: " + INR.format(x.eff) + " " + [x.type, x.number].filter(Boolean).join(" ")))
            .concat(differ.filter(p => V[p.v].date === d || T[p.t].date === d).map(p => "amount differs: vendor " + INR.format(Math.abs(V[p.v].eff)) + ", Tally " + INR.format(Math.abs(T[p.t].eff)) + " (" + [T[p.t].type, T[p.t].number].filter(Boolean).join(" ") + ")"))
            .concat(pairs.concat(differ).filter(p => (V[p.v].date === d) !== (T[p.t].date === d) && (V[p.v].date === d || T[p.t].date === d)).map(p => "same entry on another date: " + fmtDate(V[p.v].date) + " (vendor) / " + fmtDate(T[p.t].date) + " (Tally)"));
          timeline.push({date: d, diff, change: r2(diff - prev), why});
          prev = diff;
        }
      });
    }
    V0.res = {at: Date.now(), company: tname, ledger, from: V0.from, to: V0.to, file: V0.fileName, method: parsed.method || "", sides: s === 1 ? "vendor's books (their debit is a bill to us)" : "our account copy (credit is a bill)",
      V, T, pairs, differ, onlyV: onlyV.map(x => x.i), onlyT: onlyT.map(x => x.i), tOpen, tClose, vOpen, vClose, openDiff, vEff, tEff, dEff, unexplained, timeline, how: tb.how};
    V0.busy = "";
    render();
  } catch (e){ V0.busy = ""; toast("Could not reconcile: " + (e.message || e.code || e)); render(); }
}

// the vendor reconciliation page: React (app/src/screens/VendorRecon.jsx), shown on the purchase bills tab
function sum0(list){ return r2(list.reduce((a, x) => a + Math.abs(x.eff), 0)); }

