  add("Matched", [["Vendor date", "Vendor particulars", "Tally date", "Tally voucher", "Amount"]].concat(R.pairs.map(p => [d(V[p.v].date), V[p.v].narr, d(T[p.t].date), [T[p.t].type, T[p.t].number].join(" "), V[p.v].eff])));
