    if (to.act === "misPack"){ this.open("mis-summary"); setTimeout(() => { const bt = document.querySelector('[data-act="misPack"]'); if (bt) bt.click(); }, 50); return; }
    if (to.gst){ FC.go("gst", {gstPart: to.gst}); return; }
