    try { s.stores.forEach((st, i) => { if ((s.held && s.held.has(st.hold)) || ch.some(c => c.i === i)) st.persist(ch.filter(c => c.i === i).map(c => c.path)); if (st.after && ch.some(c => c.i === i)) st.after(); }); }
