      if (v.opt || v.cancel) return;
      const rec = e => { const k = Books.ledgerOf(e.l).kind || ""; const w = (Books.ledgerOf(e.l).what || ""); return k === "tds_receivable" || k === "tcs_receivable" || w === "tds_receivable" || w === "tcs_receivable"; };
