      if (!c.length) return;
      c.sort((a, b) => ((a.q === l.q ? 0 : 1) - (b.q === l.q ? 0 : 1)) || Math.abs(Date.parse(tallyDate(a.date)) - Date.parse(tallyDate(l.date))) - Math.abs(Date.parse(tallyDate(b.date)) - Date.parse(tallyDate(l.date))));
