  newChat(){ const a = this.st(), k = this.key(); a.by[k] = []; delete a.chatIds[k]; a.saveOn = false; this.draw(); },
  // ---------- Settings › Assistant (the owner): today's use, the cap, the days, the questions, the mismatches
